css:
/* 赛博渐变 · Cyber Gradients
   近黑底 + 电子霓虹：青、洋红、日落珊瑚。面板切角、扫描线、发光描边，
   标签一律等宽大写。仍然是纯 CSS。 */

html[data-theme] {
  color-scheme: dark;
  --bg: #04060d;
  --ink: #e7f7ff; --muted: #90a6c4; --dim: #5f7392;
  --soft: #bcd3ea; --meta: #8fa6c4; --bright: #ffffff;
  --line: rgba(0, 229, 255, 0.22); --line2: rgba(0, 229, 255, 0.1);
  --accent: #00e5ff; --accent2: #ff2fb0; --accentText: #021016;
  --good: #4dffb8; --warn: #ff6a3d;
  --glow1: rgba(0, 229, 255, 0.24); --glow2: rgba(255, 47, 176, 0.22);
  --panel: rgba(8, 14, 26, 0.72); --panel2: rgba(12, 22, 38, 0.82);
  --dock1: rgba(8, 15, 28, 0.82); --dock2: rgba(4, 8, 16, 0.94);
  --glass: rgba(6, 12, 22, 0.78);
  --track: rgba(0, 229, 255, 0.14); --scroll: rgba(0, 229, 255, 0.4); --coverbg: #071019;
  --menu: rgba(6, 12, 24, 0.96); --menu1: rgba(10, 20, 36, 0.96); --menu2: rgba(4, 8, 16, 0.98); --chev: #4f7f9a;
  --edge: rgba(0, 229, 255, 0.35); --edge2: rgba(255, 47, 176, 0.35);
  --hover: rgba(0, 229, 255, 0.08); --tick: rgba(0, 229, 255, 0.3);
  --inset: rgba(255, 255, 255, 0.2); --wordactive: #ffffff; --swborder: rgba(0, 229, 255, 0.45);
  --shadow-dock: 0 0 0 1px rgba(0, 229, 255, 0.4), 0 30px 80px -30px rgba(0, 229, 255, 0.35);
  --serif: "Eurostile", "Bahnschrift", "Segoe UI Variable Display", "PingFang SC", sans-serif;
  --bottom: 140px;
  --shell-nav: rgba(4, 10, 20, 0.86); --shell-nav2: rgba(4, 10, 20, 0.86);
  --shell-navin: #dff6ff; --shell-navmuted: #8fb0cb; --shell-navline: rgba(0, 229, 255, 0.24);
}

html[data-theme] body {
  background:
    linear-gradient(rgba(0, 229, 255, 0.05) 1px, transparent 1px) 0 0 / 44px 44px,
    linear-gradient(90deg, rgba(0, 229, 255, 0.05) 1px, transparent 1px) 0 0 / 44px 44px,
    radial-gradient(900px 600px at 12% -10%, rgba(0, 229, 255, 0.3), transparent 62%),
    radial-gradient(820px 560px at 92% 0%, rgba(255, 47, 176, 0.26), transparent 66%),
    radial-gradient(760px 520px at 56% 108%, rgba(255, 106, 61, 0.2), transparent 64%),
    #04060d;
}
html[data-theme] body::after {
  content: ""; position: fixed; inset: 0; pointer-events: none; z-index: 1;
  background: repeating-linear-gradient(180deg, rgba(255, 255, 255, 0.035) 0 1px, transparent 1px 3px);
  mix-blend-mode: overlay;
}

/* 侧栏：切角控制台 */
html[data-theme] .sidebar {
  margin: 14px 0 14px 14px; padding: 24px 14px;
  border: 1px solid rgba(0, 229, 255, 0.3); border-radius: 4px;
  clip-path: polygon(0 0, calc(100% - 18px) 0, 100% 18px, 100% 100%, 18px 100%, 0 calc(100% - 18px));
  background: linear-gradient(180deg, rgba(8, 18, 32, 0.9), rgba(3, 7, 14, 0.94));
  box-shadow: inset 0 0 40px rgba(0, 229, 255, 0.08);
}
html[data-theme] .brand { padding: 2px 8px 22px; border-bottom: 1px solid rgba(0, 229, 255, 0.2); margin-bottom: 16px; }
html[data-theme] .brand .brand-name, html[data-theme] .brand strong {
  font-family: var(--serif); text-transform: uppercase; letter-spacing: 0.16em; color: #c9f7ff;
}
html[data-theme] .nav button {
  border: 1px solid transparent; border-radius: 2px; font-family: var(--mono); font-size: 10.5px;
  letter-spacing: 0.14em; text-transform: uppercase; color: #8fb0cb;
}
html[data-theme] .nav button:hover { color: #dff6ff; border-color: rgba(0, 229, 255, 0.28); background: rgba(0, 229, 255, 0.06); }
html[data-theme] .nav button.active {
  color: #061018; background: linear-gradient(96deg, #00e5ff, #7cf0ff);
  box-shadow: 0 0 22px rgba(0, 229, 255, 0.55);
}

/* 顶栏 */
html[data-theme] .topbar {
  margin-top: 14px; padding: 0 18px; height: 62px;
  border: 1px solid rgba(0, 229, 255, 0.26); border-radius: 4px;
  background: linear-gradient(180deg, rgba(8, 16, 30, 0.8), rgba(4, 8, 16, 0.86));
  box-shadow: 0 0 30px -12px rgba(0, 229, 255, 0.4), inset 0 1px 0 rgba(0, 229, 255, 0.2);
}
html[data-theme] .search-global { border: 1px solid rgba(0, 229, 255, 0.24); border-radius: 2px; background: rgba(0, 229, 255, 0.05); }
html[data-theme] .icon-btn { border: 1px solid rgba(0, 229, 255, 0.24); border-radius: 2px; background: transparent; }

/* 首页：标题走霓虹渐变，边框只亮左与下 */
html[data-theme] .ledger-mast {
  margin-top: 22px; padding: 34px 32px; border: 1px solid rgba(0, 229, 255, 0.34); border-radius: 4px;
  clip-path: polygon(0 0, calc(100% - 26px) 0, 100% 26px, 100% 100%, 0 100%);
  background:
    linear-gradient(120deg, rgba(0, 229, 255, 0.1), transparent 46%),
    radial-gradient(600px 300px at 92% -20%, rgba(255, 47, 176, 0.28), transparent 66%),
    rgba(5, 10, 20, 0.72);
  box-shadow: inset 0 1px 0 rgba(0, 229, 255, 0.35), 0 40px 90px -60px rgba(0, 229, 255, 0.55);
}
html[data-theme] .ledger-mast h1, html[data-theme] .ledger-mast .mast-title {
  font-family: var(--serif); font-size: clamp(38px, 5vw, 66px); line-height: 1; letter-spacing: 0.02em;
  text-transform: uppercase;
  background: linear-gradient(96deg, #b8fbff, #00e5ff 40%, #ff2fb0 82%, #ff6a3d);
  -webkit-background-clip: text; background-clip: text; color: transparent;
  filter: drop-shadow(0 0 24px rgba(0, 229, 255, 0.35));
}
html[data-theme] .ledger-mast p, html[data-theme] .subtitle { color: #90a6c4; font-family: var(--mono); font-size: 11px; letter-spacing: 0.06em; }

/* 卡片 */
html[data-theme] .card, html[data-theme] .pod-card, html[data-theme] .continue {
  border: 1px solid rgba(0, 229, 255, 0.22); border-radius: 4px;
  background: linear-gradient(160deg, rgba(10, 20, 36, 0.74), rgba(4, 8, 16, 0.86));
  box-shadow: inset 0 1px 0 rgba(0, 229, 255, 0.16);
  backdrop-filter: none; -webkit-backdrop-filter: none;
}
html[data-theme] .pod-card:hover, html[data-theme] .continue:hover {
  border-color: rgba(255, 47, 176, 0.55); box-shadow: 0 0 30px -10px rgba(255, 47, 176, 0.5); transform: translateY(-2px);
}
html[data-theme] .btn { border: 1px solid rgba(0, 229, 255, 0.4); border-radius: 2px; background: rgba(0, 229, 255, 0.08); color: #d7fbff; font-family: var(--mono); letter-spacing: 0.08em; text-transform: uppercase; font-size: 10.5px; }
html[data-theme] .btn.primary { background: linear-gradient(96deg, #00e5ff, #ff2fb0); color: #05070d; border: 0; }

/* 统计 */
html[data-theme] #page-stats .page-head {
  margin: 18px 0; padding: 30px 32px; border: 1px solid rgba(0, 229, 255, 0.3); border-radius: 4px;
  clip-path: polygon(0 0, calc(100% - 22px) 0, 100% 22px, 100% 100%, 0 100%);
  background: linear-gradient(130deg, rgba(0, 229, 255, 0.1), rgba(255, 47, 176, 0.08)), rgba(4, 9, 18, 0.7);
}
html[data-theme] #page-stats .page-head h1 {
  font-family: var(--serif); font-size: clamp(30px, 4.4vw, 54px); letter-spacing: 0.04em; text-transform: uppercase;
  background: linear-gradient(96deg, #ffffff, #00e5ff 48%, #ff2fb0);
  -webkit-background-clip: text; background-clip: text; color: transparent;
}
html[data-theme] #page-stats .eyebrow { color: #00e5ff; font-family: var(--mono); letter-spacing: 0.3em; }
html[data-theme] #page-stats .stat {
  border: 1px solid rgba(0, 229, 255, 0.3); border-radius: 4px; background: rgba(6, 12, 24, 0.8);
  box-shadow: inset 0 0 30px rgba(0, 229, 255, 0.06); backdrop-filter: none; position: relative; overflow: hidden;
}
html[data-theme] #page-stats .stat:before {
  content: ""; position: absolute; inset: 0 auto 0 0; width: 2px;
  background: linear-gradient(180deg, #00e5ff, #ff2fb0);
}
html[data-theme] #page-stats .stat strong {
  font-family: var(--serif); font-size: 34px; letter-spacing: 0.02em;
  background: linear-gradient(96deg, #b8fbff, #00e5ff 60%, #ff2fb0);
  -webkit-background-clip: text; background-clip: text; color: transparent;
}
html[data-theme] #page-stats .stat label, html[data-theme] #page-stats .stat em { font-family: var(--mono); color: #8fb0cb; letter-spacing: 0.1em; }
html[data-theme] #page-stats .card { padding: 22px; }
html[data-theme] #page-stats .section-title { font-family: var(--mono); text-transform: uppercase; letter-spacing: 0.12em; font-size: 12px; border-bottom: 1px solid rgba(0, 229, 255, 0.18); }
html[data-theme] #page-stats .stat-bar { border-radius: 2px; background: rgba(0, 229, 255, 0.04); border-left: 1px solid rgba(0, 229, 255, 0.24); }
html[data-theme] #page-stats .stat-track { height: 6px; border-radius: 0; background: rgba(0, 229, 255, 0.12); box-shadow: none; }
html[data-theme] #page-stats .stat-track i { border-radius: 0; background: linear-gradient(90deg, #00e5ff, #ff2fb0); box-shadow: 0 0 14px rgba(0, 229, 255, 0.7); }
html[data-theme] #page-stats .stats-year-head {
  margin-top: 30px; padding: 28px 32px; border: 1px solid rgba(255, 47, 176, 0.3); border-radius: 4px;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 22px), calc(100% - 22px) 100%, 0 100%);
  background: linear-gradient(140deg, rgba(255, 47, 176, 0.1), rgba(0, 229, 255, 0.06)), rgba(4, 9, 18, 0.72);
}
html[data-theme] #page-stats .year-title {
  font-family: var(--serif); font-size: 48px; letter-spacing: 0.03em; text-transform: uppercase;
  background: linear-gradient(96deg, #ffffff, #ff6a3d 50%, #ff2fb0);
  -webkit-background-clip: text; background-clip: text; color: transparent;
}
html[data-theme] #page-stats #echoYear { border: 1px solid rgba(0, 229, 255, 0.4); border-radius: 2px; background: rgba(0, 229, 255, 0.08); color: #d7fbff; font-family: var(--mono); }
html[data-theme] #page-stats #echoBody { padding: 22px; }

/* 设置 */
html[data-theme] .ct-box { border: 1px solid rgba(0, 229, 255, 0.28); border-radius: 4px; background: rgba(6, 12, 22, 0.7); }
html[data-theme] .ct-code, html[data-theme] #ctCss, html[data-theme] #ctHtml {
  border: 1px solid rgba(0, 229, 255, 0.25); border-radius: 2px; background: rgba(3, 8, 16, 0.8); color: #b8fbff;
}

/* 播放舱 */
@media (min-width: 901px) {
  html[data-theme] body .dock {
    left: 50%; right: auto; bottom: 16px; translate: -50% 0;
    width: min(880px, calc(100vw - 40px)); max-width: calc(100vw - 24px);
    padding: 14px 24px 16px; border: 1px solid rgba(0, 229, 255, 0.45); border-radius: 4px;
    clip-path: polygon(0 0, calc(100% - 20px) 0, 100% 20px, 100% 100%, 20px 100%, 0 calc(100% - 20px));
    background: linear-gradient(180deg, rgba(10, 20, 36, 0.86), rgba(3, 7, 14, 0.94));
    box-shadow: 0 0 40px -12px rgba(0, 229, 255, 0.5), inset 0 1px 0 rgba(0, 229, 255, 0.3);
  }
  html[data-theme] .mini-player { left: 292px; }
}
html[data-theme] .dock .playbtn { border-radius: 2px; background: linear-gradient(96deg, #00e5ff, #ff2fb0); color: #05070d; box-shadow: 0 0 24px rgba(0, 229, 255, 0.55); }
html[data-theme] .mini-player { border: 1px solid rgba(0, 229, 255, 0.35); border-radius: 4px; background: rgba(5, 10, 20, 0.9); }

html[data-theme] .cue.active .word { color: #ffffff; background: rgba(0, 229, 255, 0.16); box-shadow: 0 0 14px rgba(0, 229, 255, 0.4); }
html[data-theme] ::-webkit-scrollbar-thumb { background: rgba(0, 229, 255, 0.45); border-radius: 0; }

/* ---------- 12. 壁纸模式：全屏字幕层 ---------- */
html[data-theme] .wallpaper { background: radial-gradient(120% 100% at 16% -4%, #0a1526 0%, #04060d 58%, #010206 100%); color: #e7f7ff; }
html[data-theme] .wp-bg { filter: blur(38px) saturate(220%) brightness(.44) contrast(1.1); opacity: .88; }
html[data-theme] .wp-shade { background: linear-gradient(90deg, rgba(2,4,10,.95) 0%, rgba(6,12,26,.84) 46%, rgba(4,8,18,.68) 74%, rgba(2,4,10,.92) 100%), radial-gradient(74% 66% at 84% 16%, rgba(0,229,255,.2), transparent 64%), radial-gradient(60% 50% at 18% 84%, rgba(255,47,176,.16), transparent 66%); }
html[data-theme] .wp-kicker { color: #00e5ff; font-weight:700;letter-spacing:.3em; }
html[data-theme] .wp-title { color: #e7f7ff; font-weight:700;letter-spacing:-.02em;text-transform:uppercase; }
html[data-theme] .wp-cue.past, html[data-theme] .wp-cue.future { color: rgba(160,200,225,.8); }
html[data-theme] .wp-cue.active::before { background: linear-gradient(180deg, #00e5ff, #ff2fb0); box-shadow: 0 0 30px rgba(0,229,255,.6); width:clamp(4px,.3vw,5px);border-radius:0;clip-path:polygon(0 0,100% 0,100% 86%,0 100%); }
html[data-theme] .wp-cue.active .wp-en { color: #ffffff; text-shadow: 0 0 26px rgba(0,229,255,.5); font-weight:700;letter-spacing:-.03em; }
html[data-theme] .wp-word.past { color: #e7f7ff; }
html[data-theme] .wp-word.active { color: #ffffff; background-image: linear-gradient(180deg, transparent 58%, rgba(0,229,255,.45) 58%, rgba(255,47,176,.3) 94%, transparent 94%); text-shadow: 0 0 24px rgba(0,229,255,.55); border-radius:0; }
html[data-theme] .wp-zh { color: rgba(144,166,196,.8); font-weight:400;letter-spacing:.02em; }
html[data-theme] .wp-label { color: rgba(144,166,196,.5); }
html[data-theme] .wpbtn { background: rgba(6,12,24,.78); border-color: rgba(0,229,255,.4); color: #e7f7ff; border-radius:2px;clip-path:polygon(8px 0,100% 0,100% calc(100% - 8px),calc(100% - 8px) 100%,0 100%,0 8px);letter-spacing:.1em;text-transform:uppercase; }
html[data-theme] .wpbtn:hover { background: rgba(0,229,255,.16); border-color: #00e5ff; color: #ffffff; }
html[data-theme] .wp-shade::after { background: repeating-linear-gradient(0deg, rgba(0,229,255,.14) 0 1px, transparent 1px 3px); opacity:.5; }

/* ---------- 13. 底栏几何：与内置对齐 ---------- */
html[data-theme] body .dock {
  left: 50% !important; right: auto !important; translate: -50% 0 !important; bottom: 16px !important;
  width: min(1040px, calc(100% - 40px)) !important; max-width: none !important; margin: 0 !important;
}
html[data-theme] body.player-open .dock {
  left: 0 !important; right: 0 !important; translate: none !important; bottom: 16px !important;
  width: auto !important; max-width: min(880px, calc(100vw - 40px)) !important; margin: 0 auto !important;
}
html[data-theme] .mini-player { left: 258px; right: 20px; }
@media (max-width: 1180px) { html[data-theme] .mini-player { left: 220px; } }
@media (max-width: 900px) { html[data-theme] .mini-player { left: 10px; right: 10px; bottom: 64px; } }
html[data-theme] body.nav-collapsed .mini-player { left: 20px; right: 20px; }

/* ---------- 14. 播放工具面板（更多）：按主题重绘 ---------- */

html[data-theme] .dshead h4 { color: var(--soft, var(--muted)); }
html[data-theme] .dstile { background: var(--panel2, var(--panel)); border: 1px solid var(--line); color: var(--ink); border-radius: 12px; }
html[data-theme] .dstile svg { stroke: var(--muted); }
html[data-theme] .dstile:hover { background: var(--hover, var(--panel2)); border-color: var(--accent); color: var(--ink); }
html[data-theme] .dstile:hover svg { stroke: var(--accent); }
html[data-theme] .dstile[aria-pressed="true"], html[data-theme] .dstile[aria-expanded="true"] { border-color: var(--accent); }
html[data-theme] .dslabel { color: var(--muted); }
html[data-theme] .dspill, html[data-theme] .dsmute { background: var(--panel2, var(--panel)); border-color: var(--line); color: var(--soft, var(--ink)); }
html[data-theme] .dspill.on { color: var(--accent); border-color: var(--accent); }
html[data-theme] .dsrange { accent-color: var(--accent); }
html[data-theme] .iconbtn { background: var(--panel2, var(--panel)); border: 1px solid var(--line); color: var(--muted); }
